    <div className=\"game-result\"><p role=\"status\" aria-live=\"polite\" aria-atomic=\"true\"><span key={announcement}>{notice}</span></p></div>
    {"'!tournament && <>
      <label htmlFor="players">Players </label><select id="players" className="control" value={count} onChange={(event) => setCount(Number(event.currentTarget.value))}><option value={4}>4</option><option value={8}>8</option></select>
      <div className="player-fields">{names.slice(0, count).map((name, index) => <label key={index}>Player {index + 1}<input className="control" value={name} onChange={(event) => setNames(names.map((n, i) => i === index ? event.currentTarget.value : n))} /></label>)}</div>
      <div className="tournament-actions"><button className="control" type="button" onClick={start}>Start tournament</button><button className="control" type="button" onClick={back}>Back to game</button></div>
    </>}
    {tournament && match && <>
      {tournament.phase === '"'complete' ? <><p>Champion: {tournament.names[match.winner"'! - 1]}</p><div className="tournament-actions"><button className="control" type="button" onClick={back}>Back to game</button></div></> : <>
        <p>Round: {roundName(tournament.matches[tournament.currentRound]!.length)}</p><p>Now playing: {player}</p>
        <div className="tournament-actions">
