          {tournament.phase === '"'matchEnd' && <button className=\"control\" type=\"button\" onClick={() => { const next = nextMatch(tournament); setTournament(next); const seed = next.matches[next.currentRound]"'![next.currentMatch]!.players[0]!; publish(`Now playing: ${next.names[seed - 1]}`); }}>Next match</button>}
